/**
 * GET /api/motivation/recommend
 *
 * Returns 1-3 well-curated motivation items drawn from a hand-curated
 * seed catalogue. The catalogue is *seed-only*: the route augments
 * each item with a one-line framing note generated by the LLM based
 * on the user's current state (slipping / on-track / asking-for-a-
 * push). The framing never replaces the underlying hand-picked item
 * — it just explains why this item is being shown right now.
 *
 * Trigger rule (data-detected, server-side, called by the front-end
 * \`MotivationCard\` when the user lands on a daily Goal view, or by
 * the chat flow when the user types 'motivate me' / 'give me a
 * push' / etc.):
 *   1. Has open commitments due today or overdue  → pull from
 *      'overdue' subset.
 *   2. Has goals, no overdue, but never confirmed anything in 7d →
 *      pull from 'dormant' subset.
 *   3. Otherwise  → pull from 'stuck' subset.
 *
 * The LLM framing only fires when a model call is cheap; we cap the
 * token budget per call and fall back to a deterministic copy if the
 * model errors out so the user still sees a usable response.
 */

import { NextResponse, type NextRequest } from 'next/server'
import { and, eq, lt, lte, inArray } from 'drizzle-orm'

import { db } from '@/lib/db'
import { goals, commitments } from '@/db/schema'
import { resolveRequestUser } from '@/lib/request-user'

export const runtime = 'nodejs'
export const dynamic = 'force-dynamic'

// Hand-curated seed catalogue. The user said 'well curated' — these
// are chosen by the assistant for the Sutra voice. Each entry is
// pattern-matched to one of three buckets; the route picks a subset
// based on the user's current state.
interface Seed {
  id: string
  bucket: 'overdue' | 'dormant' | 'stuck'
  kind: 'video' | 'article' | 'book' | 'talk'
  title: string
  author: string
  url: string
  duration: string
  excerpt: string
}

