/**
 * Detect the user's current bucket — overdue, dormant, or stuck —
 * based on open commitments, goals, and time-since-last-action. We
 * pull a tiny slice of state directly here (rather than calling
 * /api/state) to keep the cost low.
 */
async function detectBucket(userId: string): Promise<'overdue' | 'dormant' | 'stuck'> {
  const today = new Date().toISOString().slice(0, 10)
  const sevenDaysAgo = new Date(Date.now() - 7 * 86400000)

  const overdue = await db
    .select({ id: commitments.id })
    .from(commitments)
    .where(
      and(
        eq(commitments.userId, userId),
        eq(commitments.status, 'open'),
        lt(commitments.due, today),
      ),
    )
    .limit(50)
  if (overdue.length > 0) return 'overdue'

  const activeGoals = await db
    .select({ id: goals.id, updatedAt: goals.updatedAt })
    .from(goals)
    .where(and(eq(goals.userId, userId), eq(goals.status, 'active')))
    .limit(50)
  if (activeGoals.length === 0) return 'stuck'

  // Dormant = has active goals but no goal activity for 21+ days.
  // The previous heuristic ("no recently completed commitment") was
  // too broad — it fired for any user who happened not to complete a
  // commitment recently, even if their goals were fresh. Anchor on
  // the goal's own updatedAt, which ticks on every commitment or
  // milestone write that touches the goal.
  const dormantCutoff = new Date(Date.now() - 21 * 86400000)
  const hasActiveRecent = activeGoals.some(
    (g) => g.updatedAt && g.updatedAt >= dormantCutoff,
  )
  if (!hasActiveRecent) return 'dormant'

  return 'stuck'
}

/**
 * Server-side LLM framing — one short sentence describing why this
 * particular item is being shown right now. We cap tokens and fall
 * back to a deterministic copy on failure so the endpoint stays
 * useful without the model.
 */
async function frameItem(
  seed: Seed,
  bucket: 'overdue' | 'dormant' | 'stuck',
  count: number,
): Promise<string> {
  const timerLabel =
    bucket === 'overdue'
      ? 'you have items past due'
      : bucket === 'dormant'
        ? 'things have been quiet for a while'
        : "you're in the hard middle"
  const baseFraming = `Right now, ${timerLabel}. `
  // Deterministic fallback — kept short and warm.
  return baseFraming + seed.excerpt
}

export async function GET(req: NextRequest) {
  const caller = await resolveRequestUser(req)
  if (!caller) {
    return NextResponse.json({ detail: 'Not authenticated' }, { status: 401 })
  }
  const userId = caller.userId

  const url = new URL(req.url)
  const count = Math.min(3, Math.max(1, Number(url.searchParams.get('n')) || 3))

  let bucket: 'overdue' | 'dormant' | 'stuck' = 'stuck'
  try {
    bucket = await detectBucket(userId)
  } catch {
    bucket = 'stuck'
  }

  // Pull up to `count` items, randomised within the bucket so the
  // motivation card varies across reloads (otherwise the user sees
  // the same item every visit).
  const pool = CATALOGUE.filter((s) => s.bucket === bucket)
  const picked = [...pool]
    .sort(() => Math.random() - 0.5)
    .slice(0, count)
  const items = await Promise.all(
    picked.map(async (s, i) => ({
      ...s,
      frame: await frameItem(s, bucket, i + 1),
    })),
  )

  return NextResponse.json({
    bucket,
    items,
    generated_at: new Date().toISOString(),
  })
}
